13	  private readonly selectedSeatsState = signal<SelectedSeat[]>([]);
14	  private readonly priceCategoriesState = signal<PriceCategory[]>([]);
15	
16	  readonly selectedSeats = this.selectedSeatsState.asReadonly();
17	
18	  readonly allSelectedSeatsHaveCategory = computed(() =>
