    expect(() => parseSeatCode('3B')).toThrow();
  });

  it('wirft bei einem Code ohne Spaltennummer', () => {
    expect(() => parseSeatCode('B')).toThrow();
  });

  it('wirft bei einem leeren Code', () => {
    expect(() => parseSeatCode('')).toThrow();
  });
});

